BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL statement_timeout='30s';
SELECT jsonb_build_object(
  'database', current_database(),
  'readerRole', current_user,
  'postgresVersion', current_setting('server_version'),
  'appliedMigrations', (SELECT count(*) FROM public."_prisma_migrations" WHERE finished_at IS NOT NULL AND rolled_back_at IS NULL),
  'unfinishedMigrations', (SELECT count(*) FROM public."_prisma_migrations" WHERE finished_at IS NULL AND rolled_back_at IS NULL),
  'rolledBackMigrations', (SELECT count(*) FROM public."_prisma_migrations" WHERE rolled_back_at IS NOT NULL),
  'publicTables', (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p')),
  'customerStageOneApplied', (SELECT count(*) FROM public."_prisma_migrations" WHERE migration_name='20261003120000_customer_stage_one' AND finished_at IS NOT NULL AND rolled_back_at IS NULL)
) AS metadata;
COMMIT;

