BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL statement_timeout='30s';
SELECT migration_name, checksum, finished_at IS NOT NULL AS finished, rolled_back_at IS NOT NULL AS rolled_back FROM public."_prisma_migrations" ORDER BY started_at;
SELECT rolname, rolsuper, rolinherit, rolcreaterole, rolcreatedb, rolcanlogin, rolreplication, rolbypassrls FROM pg_roles WHERE rolname IN ('kortek_runtime','kortek_migrator');
SELECT member.rolname AS member, parent.rolname AS parent FROM pg_auth_members am JOIN pg_roles member ON member.oid=am.member JOIN pg_roles parent ON parent.oid=am.roleid WHERE member.rolname IN ('kortek_runtime','kortek_migrator') OR parent.rolname IN ('kortek_runtime','kortek_migrator');
SELECT pg_get_userbyid(datdba) AS database_owner FROM pg_database WHERE datname=current_database();
SELECT pg_get_userbyid(c.relowner) AS owner, count(*) AS tables FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p') GROUP BY c.relowner;
SELECT count(*) AS clients, count(*) FILTER (WHERE "userId" IS NOT NULL) AS linked_clients FROM public."Client";
SELECT count(*) AS bookings, count(*) FILTER (WHERE "clientId" IS NOT NULL) AS bookings_with_client FROM public."Booking";
SELECT count(*) AS linked_clients_with_bookings FROM public."Client" c WHERE c."userId" IS NOT NULL AND EXISTS (SELECT 1 FROM public."Booking" b WHERE b."clientId"=c.id AND b."organizationId"=c."organizationId");
SELECT count(*) AS groups_with_same_stored_phone, coalesce(sum(n),0) AS clients_in_those_groups FROM (SELECT count(*) AS n FROM public."Client" c WHERE c.phone IS NOT NULL AND EXISTS (SELECT 1 FROM public."Booking" b WHERE b."clientId"=c.id AND b."organizationId"=c."organizationId") GROUP BY c."organizationId", c.phone HAVING count(*)>1) g;
COMMIT;

BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL statement_timeout='30s';
SELECT jsonb_build_object(
'ledger',(SELECT jsonb_agg(jsonb_build_object('name',migration_name,'checksum',checksum,'finished',finished_at IS NOT NULL,'rolledBack',rolled_back_at IS NOT NULL) ORDER BY started_at) FROM public."_prisma_migrations"),
'roles',(SELECT jsonb_agg(jsonb_build_object('role',rolname,'super',rolsuper,'inherit',rolinherit,'createRole',rolcreaterole,'createDb',rolcreatedb,'login',rolcanlogin,'replication',rolreplication,'bypassRls',rolbypassrls)) FROM pg_roles WHERE rolname IN ('kortek_runtime','kortek_migrator')),
'memberships',(SELECT coalesce(jsonb_agg(jsonb_build_object('member',member.rolname,'parent',parent.rolname)),'[]'::jsonb) FROM pg_auth_members am JOIN pg_roles member ON member.oid=am.member JOIN pg_roles parent ON parent.oid=am.roleid WHERE member.rolname IN ('kortek_runtime','kortek_migrator') OR parent.rolname IN ('kortek_runtime','kortek_migrator')),
'databaseOwner',(SELECT pg_get_userbyid(datdba) FROM pg_database WHERE datname=current_database()),
'tableOwners',(SELECT jsonb_agg(jsonb_build_object('owner',owner,'count',n)) FROM (SELECT pg_get_userbyid(c.relowner) AS owner,count(*) AS n FROM pg_class c JOIN pg_namespace s ON s.oid=c.relnamespace WHERE s.nspname='public' AND c.relkind IN ('r','p') GROUP BY c.relowner) x),
'clients',(SELECT count(*) FROM public."Client"),
'linkedClients',(SELECT count(*) FROM public."Client" WHERE "userId" IS NOT NULL),
'bookings',(SELECT count(*) FROM public."Booking"),
'bookingsWithClient',(SELECT count(*) FROM public."Booking" WHERE "clientId" IS NOT NULL),
'linkedClientsWithBookings',(SELECT count(*) FROM public."Client" c WHERE c."userId" IS NOT NULL AND EXISTS (SELECT 1 FROM public."Booking" b WHERE b."clientId"=c.id AND b."organizationId"=c."organizationId")),
'phoneGroups',(SELECT count(*) FROM (SELECT c."organizationId",c.phone FROM public."Client" c WHERE c.phone IS NOT NULL AND EXISTS(SELECT 1 FROM public."Booking" b WHERE b."clientId"=c.id AND b."organizationId"=c."organizationId") GROUP BY c."organizationId",c.phone HAVING count(*)>1) x)
) AS preflight;
COMMIT;
